code.formula:
v_NomTable := "Statuts";
v_Cle := Tele_Statut;


REM {Obtenir l'emplacement de la base de documents du GDK};
v_serveurWDist := @IfError(@DbLookup(""; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_NDB20"; "SI Distributions"; 2); "");
v_fichierWDist := @IfError(@DbLookup(""; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_NDB20"; "SI Distributions"; 3); "");


v_Valeurs := @DbLookup( "" : "NoCache"; v_serveurWDist : v_fichierWDist; "V_Tabl20"; v_NomTable; 4);
@If(@IsError(v_Valeurs); @Return(""); "");
v_Descriptions := @DbLookup( "" : "NoCache"; "" : ""; "V_Tabl20"; v_NomTable; 10);
@If(@IsError(v_Descriptions); @Return(""); "");

v_Position := @Member(V_Cle; v_Valeurs);
@If(v_Position = 0; ""; @Subset(@Subset(v_Descriptions; v_Position); -1))

v_VuePL := "V_Clie10";
v_Titre := "Sélection d'un client";
v_Texte := "Sélectionnez un client et appuyez sur OK";
v_Colonne := 4;

REM {Sélectionner un client};
v_Valeur := @PickList([Custom]; SF_ServeurSICl : SF_FichierSICl; v_VuePL ; v_Titre; v_Texte; v_Colonne);
@If(v_Valeur = ""; @Return(""); "");

REM {Mettre à jour les champs du document};
FIELD Tele_Acces := @Trim(Tele_Acces : v_Valeur);
@Command([ViewRefreshFields])

v_nomClie1 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Tele_Acces; 14); "");
v_nomClie2 :=@IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Tele_Acces; 15); "");
v_nomClie1 + " " + v_nomClie2

@Return(@True);
@If((@IsNull(@ThisValue) & DB_HebergementMedi_1 = 0) | Tele_TypeFichier = "9"; @Success;
DB_HebergementMedi_1 > 0 & @IsNull(@ThisValue); @Failure("Le fichier de sauvegarde est obligatoire.");
!@Contains(@ThisValue; "."); @Failure("Le fichier de sauvegarde est invalide.");
!@IsNull(@ThisValue) & !@IsNull(Tele_PathFichierInstall);
@If(@Length(@ThisValue) - @Length(@ReplaceSubstring(@ThisValue;".";"")) !=@Length(Tele_PathFichierInstall) - @Length(@ReplaceSubstring(Tele_PathFichierInstall;".";"")) ; @Failure("Le nombre de " + "\".\""  + " du fichier de sauvegarde ne correspond pas à celui du fichier de distribution.") ;
@Right(@LowerCase(@ThisValue); 5) = ".savf"; @Success; @Failure("Le fichier de sauvegarde doit avoir l'extension .savf pour être valide.")); @Success)
